findings.suggestion:
const done = newestFirst
  .slice(0, at)
  .find((row) => row.type === 'session_done' || row.type === 'steer');
const pin = openPullRequest(newestFirst)?.sha ?? '';
const isOpenRound = newestFirst[at]?.type === 'fix_round' && done?.type === 'session_done';
